def compare_one(a, b):
    def to_float(x):
        if isinstance(x, str):
            x = x.strip()
            if ',' in x and '.' in x:
                if x.rfind(',') > x.rfind('.'):
                    x = x.replace(',', '')
                else:
                    x = x.replace('.', '')
                    x = x.replace(',', '.')
            elif ',' in x:
                if x.count(',') == 1:
                    left, right = x.split(',')
                    if left.isdigit() and right.isdigit() and len(right) == 3:
                        x = x.replace(',', '')
                    else:
                        x = x.replace(',', '.')
                else:
                    x = x.replace(',', '')
            return float(x)
        return float(x)

    fa = to_float(a)
    fb = to_float(b)
    if fa == fb:
        return None
    return a if fa > fb else b
